INSERT INTO tb_room2 (
room_name, room_size, room_basic_person, room_max_person, room_price_weekdays, room_price_weekend, room_price_shoulder_weekdays,
room_price_shoulder_weekend, room_price_peak_weekdays, room_price_peak_weekend, room_service
)
VALUES (
#{roomName}, #{roomSize}, #{roomBasicPerson}, #{roomMaxPerson}, #{roomPriceWeekdays}, #{roomPriceWeekend}, #{roomPriceShoulderWeekdays}, #{roomPriceShoulderWeekend},
#{roomPricePeakWeekdays}, #{roomPricePeakWeekend}, #{roomService}
)
